-- stochastic-processes implementation for CovarianceEstimator
-- Assumptions: stochastic increments use the specified time step; physical SDE parameters use SI units and random draws are supplied or generated by the documented stream.
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Shared = ReplicatedStorage:WaitForChild("VectorForgeShared")
local Num = require(Shared:WaitForChild("NumericalKernels"))
local VectorForge = ReplicatedStorage:WaitForChild("VectorForge")
local LA = require(VectorForge:WaitForChild("SpectralLinearAlgebra"))

local Module = {}
function Module.Sample(samples)
    local count=#samples; assert(count>=2,"at least two samples required"); local dimensions=#samples[1]
    local mean=table.create(dimensions,0)
    for _,sample in ipairs(samples) do assert(#sample==dimensions,"sample dimension mismatch"); mean=Num.Add(mean,Num.Scale(sample,1/count)) end
    local covariance=LA.Zeros(dimensions,dimensions)
    for _,sample in ipairs(samples) do local delta=Num.Subtract(sample,mean); covariance=Num.Add(covariance,Num.Scale(LA.Outer(delta,delta),1/(count-1))) end
    return mean,covariance
end

return Module
